const categoryRepresentatives = Object.freeze({
  PDF: "merge-pdfs", Image: "image-workspace", Audio: "audio-workspace",
  Developer: "json-formatter", Writing: "text-workspace", SEO: "sitemap-xml-generator",
  Agents: "local-ai-chat", Collaboration: "workflows",
});
/** @param {string} category */
export function categoryIconSvg(category) {
  if (typeof category !== "string" || !Object.hasOwn(categoryRepresentatives, category)) throw new Error("Unknown category icon.");
  return toolIconSvg(categoryRepresentatives[category]);
}
